let idx=0, loadedWeek='w1';
function docFor(w){
  const css=w==='w1'?WEEK1_CSS:WEEK2_CSS;
  const js=w==='w1'?WEEK1_JS:WEEK2_JS;
  const label=w==='w1'?'Woche 1':'Woche 2';
  return `<!doctype html><html lang="de"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Release 2.0 – ${label}</title><style>${css}</style></head><body><header><div><strong>RELEASE 2.0</strong><span>${label} · QS-Version</span></div><div class="headright"><div id="progress">Start</div></div></header><main id="app"></main><footer>Test-Rescue-Game · Gesamt-QS v1.2</footer><script>${js.replaceAll('</script>','<\/script>')}<\/script></body></html>`;
}
function loadWeek(w, cb){loadedWeek=w; frame.onload=()=>{frame.onload=null; setTimeout(()=>cb&&cb(),20)}; frame.srcdoc=docFor(w);}
function runStep(i){idx=Math.max(0,Math.min(steps.length-1,i));const [w,label,code]=steps[idx];const execute=()=>{try{frame.contentWindow.eval(code)}catch(e){console.error(e);info.textContent='QS-Sprung konnte nicht ausgeführt werden: '+label;return}update(label)};if(loadedWeek!==w)loadWeek(w,execute);else execute()}
function update(label){info.textContent=`${idx+1} / ${steps.length} · ${label}`;back.disabled=idx===0;next.disabled=idx===steps.length-1;weekBtn.textContent=loadedWeek==='w1'?'Zu Woche 2':'Zu Woche 1'}
back.onclick=()=>runStep(idx-1);next.onclick=()=>runStep(idx+1);weekBtn.onclick=()=>{const target=loadedWeek==='w1'?steps.findIndex(x=>x[0]==='w2'):0;runStep(target)};
window.openWeek2QS=()=>runStep(steps.findIndex(x=>x[0]==='w2'));
window.addEventListener('message',e=>{if(e.data&&e.data.type==='openWeek2')window.openWeek2QS()});
loadWeek('w1',()=>update(steps[0][1]));
